        selection_html += `<option value="../${table}/index_1.html" data-content="${table.replace(/_/g, " ")} ${config.view_sizes[table] ? `<span class='badge badge-light'>${config.view_sizes[table]}</span>` : ""}">${table.replace(/_/g, " ")}</option>`;
